INSERT INTO nle_categories (id, name, description, code, is_active, sort_order, created_at) VALUES
('a1000000-0000-0000-0000-000000000001', 'Fundamentals of Nursing', 'Core nursing principles, vital signs, IV therapy, wound care, infection control, and nursing procedures', 'FUNDAMENTALS', true, 1, NOW()),
('a1000000-0000-0000-0000-000000000002', 'Medical-Surgical Nursing', 'Cardiovascular, respiratory, GI, endocrine, renal, and neurological disorders', 'MEDSURG', true, 2, NOW()),
('a1000000-0000-0000-0000-000000000003', 'Community Health Nursing', 'Epidemiology, primary health care, health promotion, disease prevention, environmental health', 'COMMUNITY', true, 3, NOW()),
('a1000000-0000-0000-0000-000000000004', 'Pediatric Nursing', 'Growth and development, common pediatric illnesses, immunization, pediatric emergencies', 'PEDIATRICS', true, 4, NOW()),
('a1000000-0000-0000-0000-000000000005', 'Obstetric Nursing', 'Prenatal care, labor and delivery, postpartum care, newborn care, family planning', 'OBSTETRIC', true, 5, NOW()),
('a1000000-0000-0000-0000-000000000006', 'Mental Health Nursing', 'Therapeutic communication, psychiatric disorders, psychopharmacology, crisis intervention', 'MENTAL', true, 6, NOW()),
('a1000000-0000-0000-0000-000000000007', 'Pharmacology', 'Drug classifications, dosage calculations, side effects, drug interactions', 'PHARMA', true, 7, NOW()),
('a1000000-0000-0000-0000-000000000008', 'Anatomy & Physiology', 'Body systems, organ functions, physiological processes', 'ANATOMY', true, 8, NOW()),
('a1000000-0000-0000-0000-000000000009', 'Microbiology & Parasitology', 'Pathogens, infection control, laboratory diagnostics', 'MICROBIO', true, 9, NOW()),
('a1000000-0000-0000-0000-000000000010', 'Nursing Leadership & Management', 'Management theories, quality improvement, healthcare policy', 'LEADERSHIP', true, 10, NOW()),
('a1000000-0000-0000-0000-000000000011', 'Ethics & Legal Issues', 'Patient rights, informed consent, professional conduct, code of ethics', 'ETHICS', true, 11, NOW()),
('a1000000-0000-0000-0000-000000000012', 'Nutrition & Dietetics', 'Nutrients, diet therapy, nutritional assessment, Philippine dietary guidelines', 'NUTRITION', true, 12, NOW()),
('a1000000-0000-0000-0000-000000000013', 'Operating Room Nursing', 'Surgical instruments, aseptic technique, surgical phases, anesthesia', 'OR_NURSING', true, 13, NOW()),
('a1000000-0000-0000-0000-000000000014', 'Emergency & Critical Care', 'Triage, CPR, trauma management, disaster nursing', 'EMERGENCY', true, 14, NOW())
INSERT INTO nle_question_bank (id, category_id, question_text, question_type, difficulty, explanation, is_high_yield, is_active, created_at, updated_at) VALUES
('b0000001-0000-0000-0000-000000000001', 'a1000000-0000-0000-0000-000000000001', 'What is the normal adult resting heart rate range?', 'MC', 'EASY', 'The normal resting heart rate for adults is 60-100 beats per minute. Rates below 60 are bradycardia and above 100 are tachycardia.', true, true, NOW(), NOW()),
('b0000001-0000-0000-0000-000000000002', 'a1000000-0000-0000-0000-000000000001', 'Which site is most accurate for taking an adult''s temperature?', 'MC', 'EASY', 'Oral temperature measurement is considered the most accurate and practical method for routine temperature assessment in adults.', true, true, NOW(), NOW()),
('b0000001-0000-0000-0000-000000000003', 'a1000000-0000-0000-0000-000000000001', 'A nurse is administering an IV medication and notices redness and swelling at the IV site. What should the nurse do first?', 'MC', 'MEDIUM', 'The nurse should immediately stop the infusion and remove the IV catheter, as these signs indicate infiltration or phlebitis. The nurse should then apply a warm compress and document the findings.', true, true, NOW(), NOW()),
('b0000001-0000-0000-0000-000000000004', 'a1000000-0000-0000-0000-000000000001', 'What is the correct order for performing hand hygiene according to WHO guidelines?', 'MC', 'MEDIUM', 'WHO recommends: wet hands, apply soap, palm to palm, right over left, left over right, interlace fingers, rub thumbs, rub fingertips, rinse, dry.', false, true, NOW(), NOW()),
('b0000001-0000-0000-0000-000000000005', 'a1000000-0000-0000-0000-000000000001', 'A patient has a wound that is clean and dry with approximated edges. What type of wound healing is occurring?', 'MC', 'MEDIUM', 'Primary intention healing occurs when wound edges are approximated, as in surgical incisions. The wound is clean and the healing process is uncomplicated.', false, true, NOW(), NOW()),
('b0000001-0000-0000-0000-000000000006', 'a1000000-0000-0000-0000-000000000001', 'What is the normal respiratory rate for an adult at rest?', 'MC', 'EASY', 'The normal respiratory rate for adults at rest is 12-20 breaths per minute. Rates below 12 indicate bradypnea and above 20 indicate tachypnea.', false, true, NOW(), NOW()),
('b0000001-0000-0000-0000-000000000007', 'a1000000-0000-0000-0000-000000000001', 'A nurse is caring for a patient on isolation precautions. Which type of isolation requires a N95 respirator?', 'MC', 'MEDIUM', 'Airborne precautions require an N95 respirator because the pathogen (e.g., tuberculosis, measles) can remain suspended in the air for extended periods.', true, true, NOW(), NOW()),
('b0000001-0000-0000-0000-000000000008', 'a1000000-0000-0000-0000-000000000001', 'What is the normal blood pressure for a healthy adult according to JNC 8 guidelines?', 'MC', 'EASY', 'Normal blood pressure is defined as systolic less than 120 mmHg and diastolic less than 80 mmHg (less than 120/80 mmHg).', true, true, NOW(), NOW()),
('b0000001-0000-0000-0000-000000000009', 'a1000000-0000-0000-0000-000000000001', 'Which of the following is the priority nursing intervention for a patient experiencing anaphylactic shock?', 'MC', 'HARD', 'Administering epinephrine is the priority intervention for anaphylaxis. Epinephrine counteracts the vasodilation and bronchoconstriction that characterize anaphylactic shock.', true, true, NOW(), NOW()),
('b0000001-0000-0000-0000-000000000010', 'a1000000-0000-0000-0000-000000000001', 'A nurse is preparing to insert a nasogastric tube. What is the correct measurement before insertion?', 'MC', 'MEDIUM', 'The NG tube should be measured from the tip of the nose to the earlobe, then from the earlobe to the xiphoid process (NEX measurement) to estimate proper insertion depth.', false, true, NOW(), NOW()),
('b0000001-0000-0000-0000-000000000011', 'a1000000-0000-0000-0000-000000000001', 'What is the normal oxygen saturation (SpO2) range for a healthy adult?', 'MC', 'EASY', 'Normal oxygen saturation for healthy adults is 95-100%. Values below 90% indicate hypoxemia and require immediate intervention.', false, true, NOW(), NOW()),
('b0000001-0000-0000-0000-000000000012', 'a1000000-0000-0000-0000-000000000001', 'A nurse is caring for a patient with a stage 2 pressure injury. What should the wound care include?', 'MC', 'HARD', 'Stage 2 pressure injuries involve partial-thick skin loss. Care includes keeping the wound moist with a hydrocolloid dressing, maintaining clean environment, and preventing further pressure.', false, true, NOW(), NOW()),
('b0000001-0000-0000-0000-000000000013', 'a1000000-0000-0000-0000-000000000001', 'Which of the following is the correct technique for measuring blood pressure using a manual sphygmomanometer?', 'MC', 'MEDIUM', 'The nurse should inflate the cuff 20-30 mmHg above the expected systolic pressure and deflate at 2-3 mmHg per second. The first Korotkoff sound indicates systolic pressure.', false, true, NOW(), NOW()),
('b0000001-0000-0000-0000-000000000014', 'a1000000-0000-0000-0000-000000000001', 'A nurse is administering blood products. Which type of blood transfusion reaction is most life-threatening?', 'MC', 'HARD', 'Hemolytic transfusion reaction is the most life-threatening because it causes massive intravascular hemolysis, leading to acute renal failure, DIC, and potentially death.', true, true, NOW(), NOW()),
('b0000001-0000-0000-0000-000000000015', 'a1000000-0000-0000-0000-000000000001', 'What is the primary purpose of using the ABCDE approach in patient assessment?', 'MC', 'MEDIUM', 'The ABCDE approach (Airway, Breathing, Circulation, Disability, Exposure) provides a systematic method for assessing and managing critically ill patients in priority order.', false, true, NOW(), NOW()),
('b0000001-0000-0000-0000-000000000016', 'a1000000-0000-0000-0000-000000000001', 'A patient has a urinary catheter in place. Which of the following nursing interventions helps prevent catheter-associated urinary tract infection (CAUTI)?', 'MC', 'MEDIUM', 'Maintaining a closed drainage system, keeping the bag below bladder level, and performing daily perineal hygiene are key interventions to prevent CAUTI.', false, true, NOW(), NOW()),
('b0000001-0000-0000-0000-000000000017', 'a1000000-0000-0000-0000-000000000001', 'What is the normal range for adult body temperature measured orally?', 'MC', 'EASY', 'The normal oral body temperature range is 36.1°C to 37.2°C (97.0°F to 99.0°F). Temperatures above 37.8°C (100°F) are considered fever.', false, true, NOW(), NOW()),
('b0000001-0000-0000-0000-000000000018', 'a1000000-0000-0000-0000-000000000001', 'A nurse is teaching a patient about proper wound care. Which instruction is correct regarding wound cleansing?', 'MC', 'MEDIUM', 'Wounds should be cleaned from the center outward in a circular motion to prevent contamination from surrounding skin into the wound bed.', false, true, NOW(), NOW()),
('b0000001-0000-0000-0000-000000000019', 'a1000000-0000-0000-0000-000000000001', 'What is the standard precautions approach to infection control?', 'MC', 'MEDIUM', 'Standard precautions assume all blood and body fluids are potentially infectious. They are applied to all patients regardless of diagnosis or presumed infection status.', true, true, NOW(), NOW()),
('b0000001-0000-0000-0000-000000000020', 'a1000000-0000-0000-0000-000000000001', 'A patient is receiving IV normal saline at 125 mL/hr. How many milliliters will the patient receive in 8 hours?', 'MC', 'EASY', '125 mL/hr × 8 hours = 1000 mL. The nurse must monitor intake and output and ensure the patient does not develop fluid overload.', false, true, NOW(), NOW()),
('b0000001-0000-0000-0000-000000000021', 'a1000000-0000-0000-0000-000000000001', 'Which of the following is the correct way to don personal protective equipment (PPE)?', 'MC', 'MEDIUM', 'The correct order is: gown, mask, goggles, gloves. This sequence minimizes contamination risk during the donning process.', true, true, NOW(), NOW()),
('b0000001-0000-0000-0000-000000000022', 'a1000000-0000-0000-0000-000000000001', 'A nurse is caring for a patient with a chest tube. Which assessment finding requires immediate intervention?', 'MC', 'HARD', 'A sudden increase in bubbling in the water seal chamber may indicate a new air leak. However, continuous bubbling when it should be intermittent is always abnormal and requires immediate attention.', false, true, NOW(), NOW()),
('b0000001-0000-0000-0000-000000000023', 'a1000000-0000-0000-0000-000000000001', 'What is the recommended position for a patient experiencing dyspnea?', 'MC', 'EASY', 'High Fowler''s position (sitting upright at 60-90 degrees) allows for maximum lung expansion and ease of breathing for patients with respiratory distress.', false, true, NOW(), NOW()),
('b0000001-0000-0000-0000-000000000024', 'a1000000-0000-0000-0000-000000000001', 'A nurse is about to perform a sterile procedure. Which of the following is considered sterile?', 'MC', 'MEDIUM', 'Only items that have been sterilized and remain within the sterile field boundaries are considered sterile. Sterile items become contaminated if touched by non-sterile objects.', false, true, NOW(), NOW()),
('b0000001-0000-0000-0000-000000000025', 'a1000000-0000-0000-0000-000000000001', 'What is the first step in the nursing process?', 'MC', 'EASY', 'Assessment is the first step in the nursing process. It involves systematic collection of patient data to establish a foundation for planning nursing care.', false, true, NOW(), NOW()),
('b0000001-0000-0000-0000-000000000026', 'a1000000-0000-0000-0000-000000000001', 'A patient on mechanical ventilation has a peak airway pressure of 45 cmH2O. What should the nurse do first?', 'MC', 'HARD', 'The nurse should first assess the patient for signs of pneumothorax, mucus plugging, or bronchospasm. High peak pressures can indicate various complications that need immediate assessment.', true, true, NOW(), NOW()),
('b0000001-0000-0000-0000-000000000027', 'a1000000-0000-0000-0000-000000000001', 'Which of the following correctly describes the purpose of a nursing care plan?', 'MC', 'MEDIUM', 'A nursing care plan serves as a guide for providing individualized, consistent, and quality nursing care. It documents patient needs, expected outcomes, and nursing interventions.', false, true, NOW(), NOW()),
('b0000001-0000-0000-0000-000000000028', 'a1000000-0000-0000-0000-000000000001', 'A nurse is performing tracheostomy suctioning. What suction pressure should be used for an adult?', 'MC', 'MEDIUM', 'The recommended suction pressure for adults is 80-150 mmHg (120 mmHg is commonly used). Pressures above 150 mmHg can damage the tracheal mucosa.', false, true, NOW(), NOW()),
('b0000001-0000-0000-0000-000000000029', 'a1000000-0000-0000-0000-000000000001', 'What is the correct method for measuring intake and output (I&O)?', 'MC', 'EASY', 'I&O should be measured and documented every shift (or more frequently for critically ill patients). All oral intake, IV fluids, and all urine, emesis, drainage, and stool output should be recorded.', false, true, NOW(), NOW()),
('b0000001-0000-0000-0000-000000000030', 'a1000000-0000-0000-0000-000000000001', 'A nurse is applying an oxygen mask to a patient. Which flow rate should be set for a simple face mask?', 'MC', 'MEDIUM', 'A simple face mask should be used with a flow rate of 6-8 L/min to prevent CO2 re-breathing. Flow rates below 6 L/min may result in CO2 retention.', false, true, NOW(), NOW()),
('b0000001-0000-0000-0000-000000000031', 'a1000000-0000-0000-0000-000000000001', 'Which of the following interventions is appropriate for a patient with dysphagia?', 'MC', 'MEDIUM', 'Patients with dysphagia should be placed in an upright position during and after meals, and thickened liquids should be provided as ordered to prevent aspiration.', false, true, NOW(), NOW()),
('b0000001-0000-0000-0000-000000000032', 'a1000000-0000-0000-0000-000000000001', 'What is the normal range for adult blood pressure according to the Philippine guidelines?', 'MC', 'EASY', 'Normal blood pressure for Filipino adults is less than 120/80 mmHg. Elevated is 120-129/<80, Stage 1 HTN is 130-139/80-89, and Stage 2 HTN is ≥140/≥90 mmHg.', false, true, NOW(), NOW()),
('b0000001-0000-0000-0000-000000000033', 'a1000000-0000-0000-0000-000000000001', 'A nurse is preparing to administer an intramuscular injection. Which site is preferred for adults?', 'MC', 'MEDIUM', 'The ventrogluteal site is preferred for IM injections in adults because it has less fat, is away from major nerves and blood vessels, and can accommodate larger volumes.', true, true, NOW(), NOW()),
('b0000001-0000-0000-0000-000000000034', 'a1000000-0000-0000-0000-000000000001', 'What is the priority nursing assessment for a patient with a central venous catheter?', 'MC', 'HARD', 'Assessment for signs of catheter-related bloodstream infection (fever, chills, redness at insertion site) and patency of the line are priority assessments for patients with CVCs.', false, true, NOW(), NOW()),
('b0000001-0000-0000-0000-000000000035', 'a1000000-0000-0000-0000-000000000001', 'A nurse is caring for a postoperative patient. Which assessment finding indicates possible hemorrhage?', 'MC', 'MEDIUM', 'Increased pulse rate, decreased blood pressure, restlessness, and cold clammy skin are classic signs of hemorrhage that require immediate assessment.', true, true, NOW(), NOW()),
('b0000001-0000-0000-0000-000000000036', 'a1000000-0000-0000-0000-000000000001', 'What is the purpose of applying an advance directive to a patient''s medical record?', 'MC', 'EASY', 'Advance directives ensure that the patient''s wishes regarding medical treatment are known and respected, especially when the patient is unable to make decisions for themselves.', false, true, NOW(), NOW()),
('b0000001-0000-0000-0000-000000000037', 'a1000000-0000-0000-0000-000000000001', 'A nurse is caring for a patient receiving enteral feeding via nasogastric tube. What is the correct position for the patient during feeding?', 'MC', 'MEDIUM', 'The patient should be in a semi-Fowler''s to high-Fowler''s position (30-45 degrees or higher) during and for at least 30 minutes after feeding to prevent aspiration.', false, true, NOW(), NOW());
INSERT INTO nle_question_bank (id, category_id, question_text, question_type, difficulty, explanation, is_high_yield, is_active, created_at, updated_at) VALUES
('b0000002-0000-0000-0000-000000000001', 'a1000000-0000-0000-0000-000000000002', 'A patient with congestive heart failure (CHF) is prescribed furosemide. Which electrolyte imbalance should the nurse monitor for?', 'MC', 'MEDIUM', 'Furosemide is a loop diuretic that causes potassium loss. Hypokalemia is a common adverse effect that can lead to cardiac arrhythmias.', true, true, NOW(), NOW()),
('b0000002-0000-0000-0000-000000000002', 'a1000000-0000-0000-0000-000000000002', 'Which of the following is a classic sign of myocardial infarction?', 'MC', 'EASY', 'Chest pain described as crushing, heavy, or squeezing that radiates to the left arm, jaw, or back is a classic sign of MI. It may be accompanied by diaphoresis, nausea, and shortness of breath.', true, true, NOW(), NOW()),
('b0000002-0000-0000-0000-000000000003', 'a1000000-0000-0000-0000-000000000002', 'A patient with pneumonia has a productive cough with rust-colored sputum. What is the most likely causative organism?', 'MC', 'MEDIUM', 'Rust-colored sputum is characteristic of Streptococcus pneumoniae, the most common cause of community-acquired pneumonia.', false, true, NOW(), NOW()),
('b0000002-0000-0000-0000-000000000004', 'a1000000-0000-0000-0000-000000000002', 'A nurse is assessing a patient with diabetes mellitus. Which finding indicates peripheral neuropathy?', 'MC', 'MEDIUM', 'Decreased sensation to monofilament testing in the feet, numbness, tingling, and burning sensations are signs of peripheral neuropathy in diabetic patients.', false, true, NOW(), NOW()),
('b0000002-0000-0000-0000-000000000005', 'a1000000-0000-0000-0000-000000000002', 'A patient with acute pancreatitis is experiencing severe abdominal pain. What is the priority nursing intervention?', 'MC', 'MEDIUM', 'Pain management is the priority intervention. Morphine may be administered, along with NPO status, IV fluid resuscitation, and nasogastric decompression if indicated.', true, true, NOW(), NOW()),
('b0000002-0000-0000-0000-000000000006', 'a1000000-0000-0000-0000-000000000002', 'Which of the following is an early sign of increased intracranial pressure (ICP)?', 'MC', 'HARD', 'Early signs of increased ICP include headache, nausea, vomiting, visual disturbances, and altered mental status. Cushing''s triad (hypertension, bradycardia, irregular respirations) is a late sign.', true, true, NOW(), NOW()),
('b0000002-0000-0000-0000-000000000007', 'a1000000-0000-0000-0000-000000000002', 'A patient with chronic obstructive pulmonary disease (COPD) is experiencing dyspnea. What is the best position for this patient?', 'MC', 'MEDIUM', 'The tripod position (sitting upright, leaning forward with arms supported) allows for maximum diaphragmatic excursion and eases the work of breathing in COPD patients.', false, true, NOW(), NOW()),
('b0000002-0000-0000-0000-000000000008', 'a1000000-0000-0000-0000-000000000002', 'A nurse is caring for a patient with a peptic ulcer. Which dietary instruction is appropriate?', 'MC', 'EASY', 'The patient should avoid spicy foods, caffeine, alcohol, and acidic foods. Small, frequent meals that are bland and easy to digest are recommended.', false, true, NOW(), NOW()),
('b0000002-0000-0000-0000-000000000009', 'a1000000-0000-0000-0000-000000000002', 'Which of the following is a priority assessment for a patient with a deep vein thrombosis (DVT)?', 'MC', 'MEDIUM', 'Assessment should include checking for calf tenderness, swelling, warmth, redness, and Homans sign. The nurse should also monitor for signs of pulmonary embolism.', true, true, NOW(), NOW()),
('b0000002-0000-0000-0000-000000000010', 'a1000000-0000-0000-0000-000000000002', 'A patient is recovering from a total hip replacement. Which position should be avoided?', 'MC', 'MEDIUM', 'Hip flexion greater than 90 degrees, adduction past midline, and internal rotation should be avoided to prevent dislocation of the prosthetic hip.', true, true, NOW(), NOW()),
('b0000002-0000-0000-0000-000000000011', 'a1000000-0000-0000-0000-000000000002', 'A patient with hyperthyroidism (Graves'' disease) is prescribed methimazole. What should the nurse monitor?', 'MC', 'MEDIUM', 'The nurse should monitor for signs of hypothyroidism (weight gain, cold intolerance, fatigue) as an adverse effect, as well as blood counts for agranulocytosis.', false, true, NOW(), NOW()),
('b0000002-0000-0000-0000-000000000012', 'a1000000-0000-0000-0000-000000000002', 'A patient with acute kidney injury has oliguria. What is the expected fluid management?', 'MC', 'HARD', 'Fluid restriction is typically ordered for oliguria in AKI. The nurse should strictly monitor intake and output, daily weights, and signs of fluid overload.', false, true, NOW(), NOW()),
('b0000002-0000-0000-0000-000000000013', 'a1000000-0000-0000-0000-000000000002', 'Which of the following is the most common complication of a stroke?', 'MC', 'MEDIUM', 'Aspiration pneumonia is one of the most common complications of stroke due to impaired swallowing mechanism. Other complications include DVT, pressure injuries, and depression.', false, true, NOW(), NOW()),
('b0000002-0000-0000-0000-000000000014', 'a1000000-0000-0000-0000-000000000002', 'A nurse is assessing a patient with heart failure. Which assessment finding indicates right-sided heart failure?', 'MC', 'MEDIUM', 'Right-sided heart failure presents with peripheral edema, jugular vein distention, hepatomegaly, and weight gain due to fluid retention.', true, true, NOW(), NOW()),
('b0000002-0000-0000-0000-000000000015', 'a1000000-0000-0000-0000-000000000002', 'A patient with diabetes mellitus type 2 is admitted with hyperglycemia. What is the priority intervention?', 'MC', 'HARD', 'Fluid and electrolyte replacement with IV fluids and insulin therapy is the priority. The nurse should monitor blood glucose levels, electrolytes, and vital signs closely.', true, true, NOW(), NOW()),
('b0000002-0000-0000-0000-000000000016', 'a1000000-0000-0000-0000-000000000002', 'Which of the following medications requires monitoring of serum digoxin levels?', 'MC', 'EASY', 'Digoxin has a narrow therapeutic index. Therapeutic levels are 0.8-2.0 ng/mL. Toxic levels can cause cardiac arrhythmias, visual disturbances, and GI symptoms.', false, true, NOW(), NOW()),
('b0000002-0000-0000-0000-000000000017', 'a1000000-0000-0000-0000-000000000002', 'A patient with liver cirrhosis develops ascites. What nursing intervention is appropriate?', 'MC', 'MEDIUM', 'Abdominal girth measurement should be performed daily, a low-sodium diet should be maintained, and diuretics may be administered as ordered. The patient should be positioned comfortably.', false, true, NOW(), NOW()),
('b0000002-0000-0000-0000-000000000018', 'a1000000-0000-0000-0000-000000000002', 'A patient is scheduled for a colonoscopy. What preparation is required the day before the procedure?', 'MC', 'MEDIUM', 'The patient should follow a clear liquid diet the day before, take prescribed bowel preparation agents (e.g., polyethylene glycol), and have nothing by mouth after midnight.', false, true, NOW(), NOW()),
('b0000002-0000-0000-0000-000000000019', 'a1000000-0000-0000-0000-000000000002', 'Which laboratory value is most important to monitor in a patient receiving warfarin therapy?', 'MC', 'EASY', 'INR (International Normalized Ratio) is the most important lab value to monitor for patients on warfarin. The therapeutic range is typically 2.0-3.0 for most indications.', true, true, NOW(), NOW()),
('b0000002-0000-0000-0000-000000000020', 'a1000000-0000-0000-0000-000000000002', 'A patient with rheumatoid arthritis is experiencing joint pain and stiffness. What is the best time for the nurse to assist with range of motion exercises?', 'MC', 'MEDIUM', 'Range of motion exercises should be performed during periods of least stiffness, typically in the afternoon or after warm compresses or a warm bath.', false, true, NOW(), NOW()),
('b0000002-0000-0000-0000-000000000021', 'a1000000-0000-0000-0000-000000000002', 'A patient with asthma is experiencing an acute attack. Which medication should the nurse administer first?', 'MC', 'MEDIUM', 'A short-acting beta-2 agonist (SABA) such as albuterol is the first-line rescue medication for acute asthma attacks due to its rapid onset of bronchodilation.', true, true, NOW(), NOW()),
('b0000002-0000-0000-0000-000000000022', 'a1000000-0000-0000-0000-000000000002', 'Which of the following is a sign of hypoglycemia in a diabetic patient?', 'MC', 'EASY', 'Signs of hypoglycemia include tremors, sweating, palpitations, hunger, confusion, and irritability. Blood glucose level below 70 mg/dL confirms hypoglycemia.', false, true, NOW(), NOW()),
('b0000002-0000-0000-0000-000000000023', 'a1000000-0000-0000-0000-000000000002', 'A nurse is caring for a patient after a thyroidectomy. Which complication should be monitored for in the immediate postoperative period?', 'MC', 'HARD', 'Hemorrhage and hematoma formation at the surgical site can compress the trachea and cause airway obstruction. The nurse should monitor for neck swelling, respiratory distress, and stridor.', true, true, NOW(), NOW()),
('b0000002-0000-0000-0000-000000000024', 'a1000000-0000-0000-0000-000000000002', 'A patient with a spinal cord injury at T6 is at risk for autonomic dysreflexia. What is the most common trigger?', 'MC', 'HARD', 'Bladder distension (from blocked catheter or constipation) is the most common trigger for autonomic dysreflexia. It presents with severe hypertension, pounding headache, and bradycardia.', false, true, NOW(), NOW()),
('b0000002-0000-0000-0000-000000000025', 'a1000000-0000-0000-0000-000000000002', 'A patient is receiving continuous IV heparin. Which laboratory value should be monitored?', 'MC', 'MEDIUM', 'aPTT (activated partial thromboplastin time) is monitored for patients on IV heparin. The therapeutic range is 1.5-2.5 times the normal control value.', false, true, NOW(), NOW()),
('b0000002-0000-0000-0000-000000000026', 'a1000000-0000-0000-0000-000000000002', 'Which of the following is a classic sign of Cushing syndrome?', 'MC', 'MEDIUM', 'Classic signs include moon face, buffalo hump, truncal obesity, purple striae, easy bruising, and hyperglycemia. These result from excess cortisol production.', true, true, NOW(), NOW()),
('b0000002-0000-0000-0000-000000000027', 'a1000000-0000-0000-0000-000000000002', 'A patient with a colostomy is being discharged. Which instruction is most important for stoma care?', 'MC', 'MEDIUM', 'The patient should be taught to clean the peristomal skin with warm water, ensure the appliance fits snugly, and monitor for signs of skin irritation or breakdown.', false, true, NOW(), NOW()),
('b0000002-0000-0000-0000-000000000028', 'a1000000-0000-0000-0000-000000000002', 'A nurse is assessing a patient with suspected appendicitis. Which finding is most characteristic?', 'MC', 'MEDIUM', 'McBurney''s point tenderness (one-third the distance from the anterior superior iliac spine to the umbilicus) is the hallmark finding of appendicitis.', false, true, NOW(), NOW()),
('b0000002-0000-0000-0000-000000000029', 'a1000000-0000-0000-0000-000000000002', 'A patient with a history of seizures is being discharged on phenytoin. Which instruction is most important?', 'MC', 'MEDIUM', 'The patient should be instructed to maintain good oral hygiene and have regular dental checkups, as phenytoin commonly causes gingival hyperplasia.', false, true, NOW(), NOW()),
('b0000002-0000-0000-0000-000000000030', 'a1000000-0000-0000-0000-000000000002', 'Which of the following is the most important assessment for a patient with a nasogastric tube?', 'MC', 'MEDIUM', 'Verifying proper tube placement is the most important assessment. This is done by checking gastric pH, observing for chest X-ray confirmation, and assessing for tube migration.', true, true, NOW(), NOW()),
('b0000002-0000-0000-0000-000000000031', 'a1000000-0000-0000-0000-000000000002', 'A patient with hypothyroidism is prescribed levothyroxine. What should the nurse teach the patient?', 'MC', 'MEDIUM', 'Levothyroxine should be taken on an empty stomach, 30-60 minutes before breakfast, and should not be taken with calcium or iron supplements which can decrease absorption.', false, true, NOW(), NOW()),
('b0000002-0000-0000-0000-000000000032', 'a1000000-0000-0000-0000-000000000002', 'A patient with congestive heart failure is placed on a fluid restriction of 1500 mL/day. How should the nurse manage oral care?', 'MC', 'MEDIUM', 'The nurse should provide frequent oral care with ice chips, sugar-free lozenges, and moisturizing mouth swabs to relieve thirst without exceeding fluid restrictions.', false, true, NOW(), NOW()),
('b0000002-0000-0000-0000-000000000033', 'a1000000-0000-0000-0000-000000000002', 'A patient is receiving chemotherapy and develops neutropenia. What is the priority nursing intervention?', 'MC', 'HARD', 'Implementing neutropenic precautions is priority: private room, hand hygiene, limiting visitors, and monitoring for signs of infection. Neutropenic patients are highly susceptible to infection.', true, true, NOW(), NOW()),
('b0000002-0000-0000-0000-000000000034', 'a1000000-0000-0000-0000-000000000002', 'Which of the following is a complication of long-term corticosteroid use?', 'MC', 'MEDIUM', 'Osteoporosis is a major complication of long-term corticosteroid use. Other complications include hyperglycemia, weight gain, adrenal suppression, and increased infection risk.', false, true, NOW(), NOW()),
('b0000002-0000-0000-0000-000000000035', 'a1000000-0000-0000-0000-000000000002', 'A patient with a chest tube has continuous bubbling in the water seal chamber. What should the nurse do?', 'MC', 'HARD', 'Continuous bubbling indicates an air leak. The nurse should check all connections, ensure the system is sealed, and check the insertion site for air leak. If persistent, notify the physician.', true, true, NOW(), NOW()),
('b0000002-0000-0000-0000-000000000036', 'a1000000-0000-0000-0000-000000000002', 'A patient with Addison''s disease is experiencing an adrenal crisis. What is the emergency treatment?', 'MC', 'HARD', 'IV hydrocortisone and aggressive IV fluid resuscitation with normal saline are the emergency treatments for adrenal crisis. This is a life-threatening emergency.', true, true, NOW(), NOW()),
('b0000002-0000-0000-0000-000000000037', 'a1000000-0000-0000-0000-000000000002', 'Which of the following is a common side effect of metformin in diabetic patients?', 'MC', 'EASY', 'GI disturbances including nausea, vomiting, diarrhea, and metallic taste are common side effects of metformin. Taking it with meals can help reduce GI symptoms.', false, true, NOW(), NOW());
INSERT INTO nle_question_bank (id, category_id, question_text, question_type, difficulty, explanation, is_high_yield, is_active, created_at, updated_at) VALUES
('b0000003-0000-0000-0000-000000000001', 'a1000000-0000-0000-0000-000000000003', 'What is the primary focus of community health nursing?', 'MC', 'EASY', 'Community health nursing focuses on the health of populations rather than individuals. It emphasizes health promotion, disease prevention, and improving the overall health status of communities.', true, true, NOW(), NOW()),
('b0000003-0000-0000-0000-000000000002', 'a1000000-0000-0000-0000-000000000003', 'In the Philippine health care system, what is a barangay health station (BHS)?', 'MC', 'MEDIUM', 'A barangay health station is the first level of health facility in the DOH hierarchy, providing basic health services at the community level, staffed by barangay health workers (BHWs).', true, true, NOW(), NOW()),
('b0000003-0000-0000-0000-000000000003', 'a1000000-0000-0000-0000-000000000003', 'What is the role of a community health nurse in disaster preparedness?', 'MC', 'MEDIUM', 'The community health nurse plays a key role in disaster preparedness by conducting community assessments, developing disaster plans, providing education, and coordinating relief efforts.', false, true, NOW(), NOW()),
('b0000003-0000-0000-0000-000000000004', 'a1000000-0000-0000-0000-000000000003', 'Which of the following is an example of primary health care intervention?', 'MC', 'MEDIUM', 'Immunization is a primary health care intervention aimed at preventing disease before it occurs. Other examples include health education, prenatal care, and family planning services.', false, true, NOW(), NOW()),
('b0000003-0000-0000-0000-000000000005', 'a1000000-0000-0000-0000-000000000003', 'What is the incubation period of dengue fever?', 'MC', 'MEDIUM', 'The incubation period of dengue fever is 4-10 days after the bite of an infected Aedes aegypti mosquito. Symptoms include high fever, severe headache, and joint pain.', true, true, NOW(), NOW()),
('b0000003-0000-0000-0000-000000000006', 'a1000000-0000-0000-0000-000000000003', 'Which type of epidemic curve suggests a point-source outbreak?', 'MC', 'HARD', 'A point-source epidemic curve has a sharp rise and gradual decline, with all cases occurring within one incubation period. This indicates exposure to a common source at a single point in time.', false, true, NOW(), NOW()),
('b0000003-0000-0000-0000-000000000007', 'a1000000-0000-0000-0000-000000000003', 'What is the recommended coverage for the Expanded Program on Immunization (EPI) in the Philippines?', 'MC', 'MEDIUM', 'The DOH targets at least 95% immunization coverage for all antigens in the EPI to achieve herd immunity and prevent vaccine-preventable diseases.', false, true, NOW(), NOW()),
('b0000003-0000-0000-0000-000000000008', 'a1000000-0000-0000-0000-000000000003', 'Which of the following is the most common mode of transmission of tuberculosis in the Philippines?', 'MC', 'EASY', 'Airborne transmission through droplet nuclei is the most common mode of TB transmission. When an infected person coughs or sneezes, droplet nuclei containing Mycobacterium tuberculosis are dispersed.', true, true, NOW(), NOW()),
('b0000003-0000-0000-0000-000000000009', 'a1000000-0000-0000-0000-000000000003', 'What is the purpose of contact tracing in communicable disease control?', 'MC', 'MEDIUM', 'Contact tracing aims to identify persons who have been exposed to a communicable disease, provide them with prophylaxis or treatment, and prevent further transmission.', false, true, NOW(), NOW()),
('b0000003-0000-0000-0000-000000000010', 'a1000000-0000-0000-0000-000000000003', 'A community health nurse is conducting a health survey. What is the first step in the community assessment process?', 'MC', 'MEDIUM', 'The first step is to identify and define the community, including its geographic boundaries, population characteristics, and existing health resources.', false, true, NOW(), NOW()),
('b0000003-0000-0000-0000-000000000011', 'a1000000-0000-0000-0000-000000000003', 'Which of the following is a health indicator used in community health assessment?', 'MC', 'EASY', 'Mortality rate, morbidity rate, life expectancy, infant mortality rate, and maternal mortality rate are key health indicators used in community health assessments.', false, true, NOW(), NOW()),
('b0000003-0000-0000-0000-000000000012', 'a1000000-0000-0000-0000-000000000003', 'What is the R.A. 10354 known as in the Philippines?', 'MC', 'MEDIUM', 'R.A. 10354 is the Responsible Parenthood and Reproductive Health Act of 2012, which guarantees universal access to methods of contraception, fertility control, sexual education, and maternal care.', true, true, NOW(), NOW()),
('b0000003-0000-0000-0000-000000000013', 'a1000000-0000-0000-0000-000000000003', 'A nurse is planning a health education session on hypertension prevention. Which approach is most effective?', 'MC', 'MEDIUM', 'Using the teach-back method ensures that community members have understood the health education provided. It involves asking participants to explain the information in their own words.', false, true, NOW(), NOW()),
('b0000003-0000-0000-0000-000000000014', 'a1000000-0000-0000-0000-000000000003', 'What is the incubation period for measles?', 'MC', 'EASY', 'The incubation period for measles is 10-14 days from exposure to onset of symptoms. The rash typically appears 3-5 days after the onset of fever.', false, true, NOW(), NOW()),
('b0000003-0000-0000-0000-000000000015', 'a1000000-0000-0000-0000-000000000003', 'In the context of disaster nursing, what does the term ''mitigation'' refer to?', 'MC', 'MEDIUM', 'Mitigation refers to actions taken to reduce or eliminate the long-term risk to human life and property from hazards. Examples include building codes, land-use planning, and early warning systems.', false, true, NOW(), NOW()),
('b0000003-0000-0000-0000-000000000016', 'a1000000-0000-0000-0000-000000000003', 'Which of the following is the most effective method of preventing the spread of COVID-19 in the community?', 'MC', 'MEDIUM', 'Hand hygiene, wearing face masks, maintaining physical distance, and getting vaccinated are the most effective methods for preventing COVID-19 transmission in the community.', true, true, NOW(), NOW()),
('b0000003-0000-0000-0000-000000000017', 'a1000000-0000-0000-0000-000000000003', 'What is the formula for computing crude birth rate?', 'MC', 'EASY', 'Crude Birth Rate = (Number of live births in a year / Total mid-year population) × 1000. This rate measures the number of live births per 1,000 population.', false, true, NOW(), NOW()),
('b0000003-0000-0000-0000-000000000018', 'a1000000-0000-0000-0000-000000000003', 'A nurse is conducting a home visit to a family with a newborn. What should be the priority assessment?', 'MC', 'MEDIUM', 'The priority is assessing the home environment for safety hazards, adequacy of nutrition, immunization status of the newborn, and the mother''s knowledge of newborn care.', false, true, NOW(), NOW()),
('b0000003-0000-0000-0000-000000000019', 'a1000000-0000-0000-0000-000000000003', 'What is the goal of the Philippine Plan of Action for Nutrition (PPAN)?', 'MC', 'MEDIUM', 'The PPAN aims to reduce all forms of malnutrition, particularly stunting, wasting, and underweight among children under 5 years old, through multisectoral approaches.', true, true, NOW(), NOW()),
('b0000003-0000-0000-0000-000000000020', 'a1000000-0000-0000-0000-000000000003', 'Which of the following is the best way to control malaria transmission in endemic areas?', 'MC', 'MEDIUM', 'Using insecticide-treated bed nets (ITNs), indoor residual spraying (IRS), and prompt diagnosis and treatment are the most effective strategies for malaria control.', false, true, NOW(), NOW()),
('b0000003-0000-0000-0000-000000000021', 'a1000000-0000-0000-0000-000000000003', 'What is the significance of the Barrio Health Unit in the Philippine health system?', 'MC', 'EASY', 'The Barangay Health Station serves as the frontliner in delivering primary health care services to the community, including immunization, prenatal care, family planning, and health education.', false, true, NOW(), NOW()),
('b0000003-0000-0000-0000-000000000022', 'a1000000-0000-0000-0000-000000000003', 'A nurse is investigating an outbreak of diarrhea in a community. What is the first step in outbreak investigation?', 'MC', 'MEDIUM', 'The first step is to verify the diagnosis and confirm that an outbreak is truly occurring by verifying reported cases through clinical examination and laboratory testing.', false, true, NOW(), NOW()),
('b0000003-0000-0000-0000-000000000023', 'a1000000-0000-0000-0000-000000000003', 'What is the role of the Rural Health Midwife (RHM) in the Philippines?', 'MC', 'MEDIUM', 'The RHM provides primary health care services including maternal and child health care, family planning, immunization, and health education to underserved communities.', true, true, NOW(), NOW()),
('b0000003-0000-0000-0000-000000000024', 'a1000000-0000-0000-0000-000000000003', 'What is the most important factor in preventing cholera outbreaks in the community?', 'MC', 'MEDIUM', 'Access to safe water and proper sanitation facilities are the most important factors in preventing cholera outbreaks. Cholera is transmitted through contaminated water.', true, true, NOW(), NOW()),
('b0000003-0000-0000-0000-000000000025', 'a1000000-0000-0000-0000-000000000003', 'A nurse is conducting a nutritional assessment of children in a community. What is the most reliable indicator of acute malnutrition?', 'MC', 'HARD', 'Weight-for-height (wasting) is the most reliable indicator of acute malnutrition. A weight-for-height z-score below -2 indicates acute malnutrition.', false, true, NOW(), NOW()),
('b0000003-0000-0000-0000-000000000026', 'a1000000-0000-0000-0000-000000000003', 'What is the significance of the PhilHealth program in the Philippines?', 'MC', 'EASY', 'PhilHealth provides health insurance coverage to Filipino citizens, enabling them to access affordable health care services and reducing out-of-pocket health expenditures.', false, true, NOW(), NOW()),
('b0000003-0000-0000-0000-000000000027', 'a1000000-0000-0000-0000-000000000003', 'Which of the following is a health indicator that reflects the quality of health care in a community?', 'MC', 'MEDIUM', 'Maternal mortality rate and infant mortality rate are key indicators of health care quality. High rates suggest deficiencies in maternal and child health services.', false, true, NOW(), NOW()),
('b0000003-0000-0000-0000-000000000028', 'a1000000-0000-0000-0000-000000000003', 'A nurse is planning a community health program for hypertension. Which strategy is most effective?', 'MC', 'MEDIUM', 'Community-based screening programs combined with lifestyle modification education and follow-up care are most effective for hypertension prevention and management.', false, true, NOW(), NOW()),
('b0000003-0000-0000-0000-000000000029', 'a1000000-0000-0000-0000-000000000003', 'What is the epidemiological triad in communicable disease control?', 'MC', 'EASY', 'The epidemiological triad consists of the agent (pathogen), host (susceptible person), and environment. Disease occurs when there is a breakdown in the balance among these three factors.', false, true, NOW(), NOW()),
('b0000003-0000-0000-0000-000000000030', 'a1000000-0000-0000-0000-000000000003', 'A nurse is monitoring the immunization status of children in a barangay. What is the BCG vaccine given for?', 'MC', 'EASY', 'BCG (Bacillus Calmette-Guerin) vaccine is given at birth to protect against tuberculosis, particularly severe forms like tuberculous meningitis and miliary TB.', true, true, NOW(), NOW()),
('b0000003-0000-0000-0000-000000000031', 'a1000000-0000-0000-0000-000000000003', 'What is the target population for the supplementary immunization activity (SIA) for measles?', 'MC', 'MEDIUM', 'The SIA targets children aged 6-59 months regardless of previous vaccination status to achieve and maintain measles elimination in the Philippines.', false, true, NOW(), NOW()),
('b0000003-0000-0000-0000-000000000032', 'a1000000-0000-0000-0000-000000000003', 'In disaster nursing, what does the term ''vulnerability assessment'' refer to?', 'MC', 'MEDIUM', 'Vulnerability assessment identifies communities or populations at higher risk of being affected by disasters based on factors like socioeconomic status, housing, and access to resources.', false, true, NOW(), NOW()),
('b0000003-0000-0000-0000-000000000033', 'a1000000-0000-0000-0000-000000000003', 'A nurse is conducting a community health survey on non-communicable diseases. What is the most common NCD in the Philippines?', 'MC', 'MEDIUM', 'Hypertension is the most common NCD in the Philippines, followed by diabetes mellitus, cardiovascular diseases, and chronic respiratory diseases.', false, true, NOW(), NOW()),
('b0000003-0000-0000-0000-000000000034', 'a1000000-0000-0000-0000-000000000003', 'What is the significance of community organizing in community health nursing?', 'MC', 'MEDIUM', 'Community organizing empowers community members to take an active role in identifying and addressing their health needs, leading to sustainable health improvements.', false, true, NOW(), NOW()),
('b0000003-0000-0000-0000-000000000035', 'a1000000-0000-0000-0000-000000000003', 'A nurse is educating a community about the importance of sanitation. What is the most effective way to prevent diarrheal diseases?', 'MC', 'MEDIUM', 'Handwashing with soap and clean water after defecation and before eating is the single most effective way to prevent diarrheal diseases.', true, true, NOW(), NOW()),
('b0000003-0000-0000-0000-000000000036', 'a1000000-0000-0000-0000-000000000003', 'What is the role of the Barangay Nutrition Scholar (BNS) in the Philippines?', 'MC', 'EASY', 'The BNS assists in implementing nutrition programs at the community level, including growth monitoring, nutrition education, and referral of malnourished children to health facilities.', false, true, NOW(), NOW()),
('b0000003-0000-0000-0000-000000000037', 'a1000000-0000-0000-0000-000000000003', 'A nurse is investigating a suspected food-borne illness outbreak. What is the most important specimen to collect?', 'MC', 'HARD', 'Stool specimens from affected individuals are the most important specimens to collect for identifying the causative organism in a food-borne illness outbreak.', false, true, NOW(), NOW());
INSERT INTO nle_question_bank (id, category_id, question_text, question_type, difficulty, explanation, is_high_yield, is_active, created_at, updated_at) VALUES
('b0000004-0000-0000-0000-000000000001', 'a1000000-0000-0000-0000-000000000004', 'What is the normal heart rate for a 2-year-old child at rest?', 'MC', 'EASY', 'The normal heart rate for children ages 1-3 years is 80-130 beats per minute. Heart rate decreases as children grow older.', false, true, NOW(), NOW()),
('b0000004-0000-0000-0000-000000000002', 'a1000000-0000-0000-0000-000000000004', 'A nurse is assessing a 6-month-old infant. What is the expected developmental milestone?', 'MC', 'EASY', 'By 6 months, infants can sit with support, roll over, babble, and reach for objects. They also begin to show stranger anxiety.', true, true, NOW(), NOW()),
('b0000004-0000-0000-0000-000000000003', 'a1000000-0000-0000-0000-000000000004', 'Which vaccine is given at 6 months of age in the Philippine EPI?', 'MC', 'MEDIUM', 'At 6 months, infants receive the 3rd dose of DPT-HepB-Hib and the 3rd dose of OPV. They also receive the first dose of PCV and influenza vaccine if available.', false, true, NOW(), NOW()),
('b0000004-0000-0000-0000-000000000004', 'a1000000-0000-0000-0000-000000000004', 'A child presents with a barking cough, stridor, and hoarseness. What is the most likely diagnosis?', 'MC', 'MEDIUM', 'These are classic signs of laryngotracheobronchitis (croup). The barking cough is characteristic and results from inflammation and swelling of the larynx and trachea.', true, true, NOW(), NOW()),
('b0000004-0000-0000-0000-000000000005', 'a1000000-0000-0000-0000-000000000004', 'A pediatric patient is receiving IV fluid therapy. How should the nurse calculate the maintenance fluid rate for a 20 kg child?', 'MC', 'MEDIUM', 'Using the 4-2-1 rule: first 10 kg = 100 mL/hr (4 mL/kg), next 10 kg = 100 mL/hr (2 mL/kg). Total = 200 mL/hr for the first 24 hours.', true, true, NOW(), NOW()),
('b0000004-0000-0000-0000-000000000006', 'a1000000-0000-0000-0000-000000000004', 'What is the most common cause of death from asthma in children?', 'MC', 'HARD', 'Status asthmaticus (severe, prolonged asthma attack unresponsive to standard treatment) is the most common cause of death from asthma in children.', false, true, NOW(), NOW()),
('b0000004-0000-0000-0000-000000000007', 'a1000000-0000-0000-0000-000000000004', 'A nurse is caring for a child with dehydration. Which assessment finding indicates moderate dehydration?', 'MC', 'MEDIUM', 'Moderate dehydration (5-10% weight loss) presents with decreased skin turgor, dry mucous membranes, sunken eyes, decreased urine output, and tachycardia.', false, true, NOW(), NOW()),
('b0000004-0000-0000-0000-000000000008', 'a1000000-0000-0000-0000-000000000004', 'What is the recommended position for a child experiencing a febrile seizure?', 'MC', 'MEDIUM', 'The child should be placed in the side-lying (recovery) position to prevent aspiration. Nothing should be inserted into the mouth during the seizure.', true, true, NOW(), NOW()),
('b0000004-0000-0000-0000-000000000009', 'a1000000-0000-0000-0000-000000000004', 'A nurse is assessing a newborn. What is the expected Apgar score at 1 minute if the heart rate is 100, respiratory effort is crying, muscle tone is active motion, reflex irritability is crying, and color is pink?', 'MC', 'MEDIUM', 'All five criteria score 2 points each, for a total Apgar score of 10. This indicates excellent condition at birth.', false, true, NOW(), NOW()),
('b0000004-0000-0000-0000-000000000010', 'a1000000-0000-0000-0000-000000000004', 'Which of the following is the most common congenital heart defect in children?', 'MC', 'EASY', 'Ventricular septal defect (VSD) is the most common congenital heart defect. It accounts for approximately 25-30% of all congenital heart defects.', false, true, NOW(), NOW()),
('b0000004-0000-0000-0000-000000000011', 'a1000000-0000-0000-0000-000000000004', 'A child with nephrotic syndrome is prescribed prednisone. What should the nurse monitor for as a side effect?', 'MC', 'MEDIUM', 'Corticosteroids like prednisone can cause weight gain, hypertension, hyperglycemia, osteoporosis, and increased infection risk in children with nephrotic syndrome.', false, true, NOW(), NOW()),
('b0000004-0000-0000-0000-000000000012', 'a1000000-0000-0000-0000-000000000004', 'What is the most appropriate toy for a 9-month-old infant to promote fine motor development?', 'MC', 'EASY', 'Stacking rings or nesting cups are appropriate for 9-month-olds as they promote fine motor skills, hand-eye coordination, and cause-and-effect learning.', false, true, NOW(), NOW()),
('b0000004-0000-0000-0000-000000000013', 'a1000000-0000-0000-0000-000000000004', 'A nurse is caring for a child with leukemia. Which finding indicates a medical emergency?', 'MC', 'HARD', 'Fever above 38.3°C (101°F) in a neutropenic child with leukemia is a medical emergency requiring immediate assessment and empiric antibiotics due to risk of sepsis.', true, true, NOW(), NOW()),
('b0000004-0000-0000-0000-000000000014', 'a1000000-0000-0000-0000-000000000004', 'What is the normal respiratory rate for a 5-year-old child at rest?', 'MC', 'EASY', 'The normal respiratory rate for children ages 3-6 years is 20-25 breaths per minute. Respiratory rate decreases as children grow.', false, true, NOW(), NOW()),
('b0000004-0000-0000-0000-000000000015', 'a1000000-0000-0000-0000-000000000004', 'A child is diagnosed with asthma. Which medication is used as a long-term controller?', 'MC', 'MEDIUM', 'Inhaled corticosteroids (e.g., budesonide) are the first-line long-term controller medications for persistent asthma in children.', true, true, NOW(), NOW()),
('b0000004-0000-0000-0000-000000000016', 'a1000000-0000-0000-0000-000000000004', 'A nurse is assessing a 3-year-old child. Which behavior is developmentally appropriate for this age?', 'MC', 'MEDIUM', 'Parallel play, tantrums, using a spoon, and speaking in 3-4 word sentences are developmentally appropriate for a 3-year-old child.', false, true, NOW(), NOW()),
('b0000004-0000-0000-0000-000000000017', 'a1000000-0000-0000-0000-000000000004', 'What is the most common cause of meningitis in children aged 2 months to 5 years?', 'MC', 'MEDIUM', 'Haemophilus influenzae type b (Hib) was historically the most common cause, but with Hib vaccination, Streptococcus pneumoniae and Neisseria meningitidis are now more common.', false, true, NOW(), NOW()),
('b0000004-0000-0000-0000-000000000018', 'a1000000-0000-0000-0000-000000000004', 'A child is admitted with severe dehydration from gastroenteritis. What is the preferred IV fluid?', 'MC', 'MEDIUM', 'Normal saline (0.9% NaCl) or Lactated Ringer''s solution are preferred for initial fluid resuscitation in severe pediatric dehydration.', false, true, NOW(), NOW()),
('b0000004-0000-0000-0000-000000000019', 'a1000000-0000-0000-0000-000000000004', 'What is the normal weight gain for an infant in the first year of life?', 'MC', 'EASY', 'Infants typically double their birth weight by 5-6 months and triple it by 12 months. Average weight gain is 25-30 grams per day in the first 3 months.', false, true, NOW(), NOW()),
('b0000004-0000-0000-0000-000000000020', 'a1000000-0000-0000-0000-000000000004', 'A nurse is teaching parents about safety precautions for toddlers. Which instruction is most important?', 'MC', 'MEDIUM', 'Installing safety gates, covering electrical outlets, locking cabinets with hazardous substances, and using car seats are critical safety measures for toddlers.', true, true, NOW(), NOW()),
('b0000004-0000-0000-0000-000000000021', 'a1000000-0000-0000-0000-000000000004', 'A child with sickle cell disease is admitted with a vaso-occlusive crisis. What is the priority intervention?', 'MC', 'HARD', 'Pain management with prescribed analgesics (often opioids), IV fluid hydration, and oxygen therapy are the priority interventions for vaso-occlusive crisis.', true, true, NOW(), NOW()),
('b0000004-0000-0000-0000-000000000022', 'a1000000-0000-0000-0000-000000000004', 'What is the recommended feeding method for a premature infant?', 'MC', 'MEDIUM', 'Breast milk (either direct breastfeeding or expressed) is the preferred feeding method for premature infants. It provides optimal nutrition and immune protection.', false, true, NOW(), NOW()),
('b0000004-0000-0000-0000-000000000023', 'a1000000-0000-0000-0000-000000000004', 'A nurse is caring for a child with type 1 diabetes. What is the most common presenting symptom?', 'MC', 'EASY', 'Polyuria (excessive urination), polydipsia (excessive thirst), polyphagia (excessive hunger), and weight loss are the classic presenting symptoms of type 1 diabetes in children.', false, true, NOW(), NOW()),
('b0000004-0000-0000-0000-000000000024', 'a1000000-0000-0000-0000-000000000004', 'Which of the following is a priority nursing diagnosis for a child with pneumonia?', 'MC', 'MEDIUM', 'Ineffective airway clearance related to mucus production is a priority nursing diagnosis for children with pneumonia, as it directly impacts oxygenation.', false, true, NOW(), NOW()),
('b0000004-0000-0000-0000-000000000025', 'a1000000-0000-0000-0000-000000000004', 'A nurse is assessing a child with suspected rheumatic fever. Which diagnostic finding is most specific?', 'MC', 'HARD', 'Elevated ASO (anti-streptolysin O) titers are the most specific laboratory finding for recent streptococcal infection associated with rheumatic fever.', false, true, NOW(), NOW()),
('b0000004-0000-0000-0000-000000000026', 'a1000000-0000-0000-0000-000000000004', 'What is the normal blood pressure range for a 10-year-old child?', 'MC', 'MEDIUM', 'Normal blood pressure for a 10-year-old is approximately 90-110/55-70 mmHg. Blood pressure norms vary by age, sex, and height percentile.', false, true, NOW(), NOW()),
('b0000004-0000-0000-0000-000000000027', 'a1000000-0000-0000-0000-000000000004', 'A child is diagnosed with Kawasaki disease. Which complication should the nurse monitor for?', 'MC', 'MEDIUM', 'Coronary artery aneurysm is the most serious complication of Kawasaki disease. Echocardiography is used to monitor for cardiac involvement.', true, true, NOW(), NOW()),
('b0000004-0000-0000-0000-000000000028', 'a1000000-0000-0000-0000-000000000004', 'A nurse is administering medication to a 4-year-old child. What is the most appropriate approach?', 'MC', 'MEDIUM', 'Using a syringe rather than a spoon for liquid medications, offering a choice when possible, and using positive reinforcement are effective strategies for administering medications to preschoolers.', false, true, NOW(), NOW()),
('b0000004-0000-0000-0000-000000000029', 'a1000000-0000-0000-0000-000000000004', 'What is the most common type of childhood cancer?', 'MC', 'EASY', 'Leukemia (particularly acute lymphoblastic leukemia) is the most common type of childhood cancer, accounting for approximately 30% of all childhood malignancies.', false, true, NOW(), NOW()),
('b0000004-0000-0000-0000-000000000030', 'a1000000-0000-0000-0000-000000000004', 'A nurse is caring for a child with spina bifida. Which nursing intervention is most important?', 'MC', 'MEDIUM', 'Maintaining skin integrity over the meningocele or myelomeningocele sac is crucial. The sac should be covered with sterile, moist dressings to prevent rupture and infection.', true, true, NOW(), NOW()),
('b0000004-0000-0000-0000-000000000031', 'a1000000-0000-0000-0000-000000000004', 'What is the recommended sleep duration for school-age children (6-12 years)?', 'MC', 'EASY', 'School-age children should get 9-12 hours of sleep per 24 hours. Adequate sleep is essential for physical growth, cognitive development, and emotional well-being.', false, true, NOW(), NOW()),
('b0000004-0000-0000-0000-000000000032', 'a1000000-0000-0000-0000-000000000004', 'A child with intellectual disability is being admitted. How should the nurse communicate with this child?', 'MC', 'MEDIUM', 'Using simple, short sentences, speaking clearly, using visual aids, allowing extra time for responses, and maintaining a calm and patient approach are effective communication strategies.', false, true, NOW(), NOW()),
('b0000004-0000-0000-0000-000000000033', 'a1000000-0000-0000-0000-000000000004', 'A nurse is assessing a newborn for congenital hip dysplasia. Which assessment technique is used?', 'MC', 'MEDIUM', 'The Ortolani and Barlow maneuvers are used to assess for congenital hip dysplasia. They involve adduction and abduction of the hips to detect dislocation or subluxation.', false, true, NOW(), NOW()),
('b0000004-0000-0000-0000-000000000034', 'a1000000-0000-0000-0000-000000000004', 'A child is receiving chemotherapy and develops mucositis. What is the appropriate nursing care?', 'MC', 'MEDIUM', 'Oral care with saline rinses, avoiding spicy and acidic foods, using a soft toothbrush, and providing prescribed mouthwashes (e.g., saline, baking soda solution) are key interventions.', false, true, NOW(), NOW()),
('b0000004-0000-0000-0000-000000000035', 'a1000000-0000-0000-0000-000000000004', 'What is the normal fontanelle closure time for the posterior fontanelle?', 'MC', 'EASY', 'The posterior fontanelle typically closes by 2-3 months of age. The anterior fontanelle closes between 12-18 months of age.', false, true, NOW(), NOW()),
('b0000004-0000-0000-0000-000000000036', 'a1000000-0000-0000-0000-000000000004', 'A child with autism spectrum disorder is admitted to the hospital. Which intervention is most therapeutic?', 'MC', 'MEDIUM', 'Maintaining a structured routine, minimizing sensory stimuli, providing visual schedules, and using clear, concrete language are therapeutic interventions for children with ASD.', false, true, NOW(), NOW()),
('b0000004-0000-0000-0000-000000000037', 'a1000000-0000-0000-0000-000000000004', 'A nurse is preparing a 7-year-old child for surgery. What is the best way to explain the procedure?', 'MC', 'MEDIUM', 'Using simple, honest language, explaining what the child will see and feel, using dolls or pictures to demonstrate, and addressing the child''s fears directly are effective approaches.', false, true, NOW(), NOW());
INSERT INTO nle_question_bank (id, category_id, question_text, question_type, difficulty, explanation, is_high_yield, is_active, created_at, updated_at) VALUES
('b0000005-0000-0000-0000-000000000001', 'a1000000-0000-0000-0000-000000000005', 'What is the most common cause of maternal mortality in the Philippines?', 'MC', 'MEDIUM', 'Postpartum hemorrhage is the leading cause of maternal mortality in the Philippines, followed by hypertensive disorders, sepsis, and complications from unsafe abortion.', true, true, NOW(), NOW()),
('b0000005-0000-0000-0000-000000000002', 'a1000000-0000-0000-0000-000000000005', 'What is the normal duration of the first stage of labor?', 'MC', 'EASY', 'The first stage of labor (from onset of true labor to full cervical dilation) averages 12-14 hours for nulliparas and 6-8 hours for multiparas.', false, true, NOW(), NOW()),
('b0000005-0000-0000-0000-000000000003', 'a1000000-0000-0000-0000-000000000005', 'A pregnant woman at 36 weeks presents with painless vaginal bleeding. What is the most likely diagnosis?', 'MC', 'HARD', 'Painless bright red vaginal bleeding in the third trimester is characteristic of placenta previa. This is an obstetric emergency requiring immediate medical attention.', true, true, NOW(), NOW()),
('b0000005-0000-0000-0000-000000000004', 'a1000000-0000-0000-0000-000000000005', 'What is the recommended schedule for prenatal visits according to DOH guidelines?', 'MC', 'MEDIUM', 'The DOH recommends at least 4 prenatal visits: first visit in the first trimester, second visit at 5-6 months, third visit at 7-8 months, and fourth visit at 9 months.', false, true, NOW(), NOW()),
('b0000005-0000-0000-0000-000000000005', 'a1000000-0000-0000-0000-000000000005', 'A nurse is assessing a pregnant woman. What is the significance of Leopold''s maneuvers?', 'MC', 'MEDIUM', 'Leopold''s maneuvers help determine fetal lie, presentation, position, and engagement. They involve four systematic palpations of the abdomen.', true, true, NOW(), NOW()),
('b0000005-0000-0000-0000-000000000006', 'a1000000-0000-0000-0000-000000000005', 'Which of the following is a danger sign during pregnancy that requires immediate medical attention?', 'MC', 'MEDIUM', 'Severe headache, visual disturbances, epigastric pain, vaginal bleeding, and decreased fetal movement are all danger signs during pregnancy that require immediate medical attention.', true, true, NOW(), NOW()),
('b0000005-0000-0000-0000-000000000007', 'a1000000-0000-0000-0000-000000000005', 'What is the normal range for fetal heart rate during labor?', 'MC', 'EASY', 'The normal fetal heart rate is 110-160 beats per minute. The FHR should be monitored every 15-30 minutes during the first stage of labor and every 5-15 minutes during the second stage.', true, true, NOW(), NOW()),
('b0000005-0000-0000-0000-000000000008', 'a1000000-0000-0000-0000-000000000005', 'A nurse is caring for a postpartum mother. What is the expected fundal height on the first day postpartum?', 'MC', 'MEDIUM', 'The fundus should be at the level of the umbilicus (approximately 1 cm below or at the umbilicus) on the first day postpartum, then descends about 1 cm per day.', false, true, NOW(), NOW()),
('b0000005-0000-0000-0000-000000000009', 'a1000000-0000-0000-0000-000000000005', 'What is the recommended position for a pregnant woman in the third trimester to prevent supine hypotension syndrome?', 'MC', 'MEDIUM', 'Left lateral position (left side-lying) prevents the gravid uterus from compressing the inferior vena cava, which can reduce cardiac output and cause maternal hypotension.', true, true, NOW(), NOW()),
('b0000005-0000-0000-0000-000000000010', 'a1000000-0000-0000-0000-000000000005', 'A newborn is not breathing at birth. What is the first intervention in neonatal resuscitation?', 'MC', 'MEDIUM', 'Drying and stimulating the newborn is the first step in neonatal resuscitation. This simple intervention often stimulates spontaneous breathing.', false, true, NOW(), NOW()),
('b0000005-0000-0000-0000-000000000011', 'a1000000-0000-0000-0000-000000000005', 'A pregnant woman is diagnosed with gestational diabetes mellitus. What is the primary management approach?', 'MC', 'MEDIUM', 'Diet modification and regular blood glucose monitoring are the first-line management. Insulin therapy is added if blood glucose levels cannot be controlled with diet alone.', false, true, NOW(), NOW()),
('b0000005-0000-0000-0000-000000000012', 'a1000000-0000-0000-0000-000000000005', 'What is the most common position of the fetus at term?', 'MC', 'EASY', 'The most common fetal position at term is cephalic (vertex) presentation, with the head flexed and the occiput anterior. This occurs in approximately 95-97% of pregnancies.', false, true, NOW(), NOW()),
('b0000005-0000-0000-0000-000000000013', 'a1000000-0000-0000-0000-000000000005', 'A nurse is assessing a newborn. What is the expected weight loss in the first few days of life?', 'MC', 'MEDIUM', 'Newborns normally lose up to 10% of their birth weight in the first 3-4 days due to fluid loss. They should regain birth weight by 10-14 days of age.', false, true, NOW(), NOW()),
('b0000005-0000-0000-0000-000000000014', 'a1000000-0000-0000-0000-000000000005', 'What is the importance of administering Rh immune globulin (RhoGAM) to Rh-negative mothers?', 'MC', 'MEDIUM', 'RhoGAM prevents Rh sensitization in Rh-negative mothers, which can cause hemolytic disease of the newborn (HDN) in subsequent pregnancies with Rh-positive fetuses.', true, true, NOW(), NOW()),
('b0000005-0000-0000-0000-000000000015', 'a1000000-0000-0000-0000-000000000005', 'A nurse is teaching a pregnant woman about breastfeeding. When should breastfeeding be initiated after delivery?', 'MC', 'EASY', 'Breastfeeding should be initiated within the first hour after birth (early initiation). This promotes bonding, stimulates oxytocin release, and helps with uterine involution.', true, true, NOW(), NOW()),
('b0000005-0000-0000-0000-000000000016', 'a1000000-0000-0000-0000-000000000005', 'A pregnant woman at 28 weeks presents with severe headache and elevated blood pressure. What is the priority intervention?', 'MC', 'HARD', 'Magnesium sulfate administration is the priority for seizure prophylaxis in severe preeclampsia. The nurse should also prepare for possible delivery and monitor for signs of eclampsia.', true, true, NOW(), NOW()),
('b0000005-0000-0000-0000-000000000017', 'a1000000-0000-0000-0000-000000000005', 'What is the normal duration of the postpartum period?', 'MC', 'EASY', 'The postpartum period (puerperium) is typically defined as the first 6 weeks (42 days) after delivery, during which the body returns to its pre-pregnant state.', false, true, NOW(), NOW()),
('b0000005-0000-0000-0000-000000000018', 'a1000000-0000-0000-0000-000000000005', 'A nurse is caring for a mother who has just delivered via cesarean section. What is the priority postoperative assessment?', 'MC', 'MEDIUM', 'Monitoring vital signs, assessing the incision site for bleeding, checking fundal tone, and monitoring lochia are priority assessments for post-cesarean mothers.', false, true, NOW(), NOW()),
('b0000005-0000-0000-0000-000000000019', 'a1000000-0000-0000-0000-000000000005', 'What is the purpose of administering oxytocin (Pitocin) in the postpartum period?', 'MC', 'MEDIUM', 'Oxytocin promotes uterine contraction (involution) and helps prevent postpartum hemorrhage. It is also used to augment labor and control postpartum bleeding.', true, true, NOW(), NOW()),
('b0000005-0000-0000-0000-000000000020', 'a1000000-0000-0000-0000-000000000005', 'A newborn is assessed and has a heart rate of 80 bpm, weak cry, and flexed posture. What is the Apgar score?', 'MC', 'MEDIUM', 'Heart rate <100 = 1, weak cry = 1, flexed posture = 2. Total Apgar score = 4. This indicates moderate depression and may require resuscitation measures.', false, true, NOW(), NOW()),
('b0000005-0000-0000-0000-000000000021', 'a1000000-0000-0000-0000-000000000005', 'What is the most common cause of postpartum hemorrhage?', 'MC', 'MEDIUM', 'Uterine atony (failure of the uterus to contract properly after delivery) is the most common cause of postpartum hemorrhage, accounting for approximately 80% of cases.', true, true, NOW(), NOW()),
('b0000005-0000-0000-0000-000000000022', 'a1000000-0000-0000-0000-000000000005', 'A nurse is teaching a pregnant woman about danger signs during pregnancy. Which sign should be reported immediately?', 'MC', 'MEDIUM', 'Vaginal bleeding, severe abdominal pain, persistent vomiting, fever, and severe headache are danger signs that should be reported immediately during pregnancy.', false, true, NOW(), NOW()),
('b0000005-0000-0000-0000-000000000023', 'a1000000-0000-0000-0000-000000000005', 'What is the recommended iron supplementation for pregnant women in the Philippines?', 'MC', 'MEDIUM', 'The DOH recommends 30-60 mg of elemental iron daily during pregnancy, along with folic acid supplementation to prevent neural tube defects.', false, true, NOW(), NOW()),
('b0000005-0000-0000-0000-000000000024', 'a1000000-0000-0000-0000-000000000005', 'A nurse is performing a pelvic assessment. What does a negative Braxton Hicks sign indicate?', 'MC', 'HARD', 'Braxton Hicks contractions are irregular, painless uterine contractions that occur throughout pregnancy. They are considered normal and help tone the uterine muscle in preparation for labor.', false, true, NOW(), NOW()),
('b0000005-0000-0000-0000-000000000025', 'a1000000-0000-0000-0000-000000000005', 'A postpartum mother is experiencing difficulty breastfeeding. What is the best nursing intervention?', 'MC', 'MEDIUM', 'Teaching proper latch technique, ensuring comfortable positioning, encouraging frequent feeding, and providing emotional support are key interventions for breastfeeding difficulties.', false, true, NOW(), NOW()),
('b0000005-0000-0000-0000-000000000026', 'a1000000-0000-0000-0000-000000000005', 'What is the normal range for the diameter of the fetal head (biparietal diameter)?', 'MC', 'EASY', 'The biparietal diameter (BPD) is approximately 9.3 cm (3.66 inches) at term. This measurement is important for assessing fetal growth and head engagement.', false, true, NOW(), NOW()),
('b0000005-0000-0000-0000-000000000027', 'a1000000-0000-0000-0000-000000000005', 'A nurse is caring for a newborn with jaundice. What is the initial intervention for physiological jaundice?', 'MC', 'MEDIUM', 'Frequent breastfeeding (8-12 times per day) promotes bowel movements which help eliminate bilirubin. Phototherapy is used when bilirubin levels reach treatment thresholds.', false, true, NOW(), NOW()),
('b0000005-0000-0000-0000-000000000028', 'a1000000-0000-0000-0000-000000000005', 'What is the importance of the APGAR scoring system?', 'MC', 'EASY', 'The APGAR score provides a rapid assessment of the newborn''s condition at 1 and 5 minutes after birth, helping to determine the need for immediate resuscitation.', false, true, NOW(), NOW()),
('b0000005-0000-0000-0000-000000000029', 'a1000000-0000-0000-0000-000000000005', 'A pregnant woman is diagnosed with preeclampsia. Which medication is used for seizure prophylaxis?', 'MC', 'HARD', 'Magnesium sulfate is the drug of choice for seizure prophylaxis in preeclampsia and eclampsia. The therapeutic serum level is 4-7 mg/dL.', true, true, NOW(), NOW()),
('b0000005-0000-0000-0000-000000000030', 'a1000000-0000-0000-0000-000000000005', 'A nurse is monitoring a laboring woman. What is the normal pattern of cervical dilation during the active phase of labor?', 'MC', 'MEDIUM', 'During the active phase (4-10 cm dilation), the cervix dilates approximately 1.2 cm per hour for nulliparas and 1.5 cm per hour for multiparas.', false, true, NOW(), NOW()),
('b0000005-0000-0000-0000-000000000031', 'a1000000-0000-0000-0000-000000000005', 'What is the recommended immunization schedule for newborns in the Philippines?', 'MC', 'MEDIUM', 'Newborns should receive BCG and Hepatitis B birth doses within 24 hours of birth. The first dose of OPV and DPT-HepB-Hib is given at 6 weeks.', false, true, NOW(), NOW()),
('b0000005-0000-0000-0000-000000000032', 'a1000000-0000-0000-0000-000000000005', 'A nurse is assessing a newborn for congenital anomalies. What is the recommended screening for metabolic disorders?', 'MC', 'MEDIUM', 'Newborn screening (NBS) for metabolic disorders including phenylketonuria (PKU), congenital hypothyroidism, and galactosemia should be performed within 48-72 hours of birth.', true, true, NOW(), NOW()),
('b0000005-0000-0000-0000-000000000033', 'a1000000-0000-0000-0000-000000000005', 'What is the normal duration of the placental stage of labor?', 'MC', 'EASY', 'The placental (third) stage of labor typically lasts 5-30 minutes after delivery of the baby. It involves delivery of the placenta and membranes.', false, true, NOW(), NOW()),
('b0000005-0000-0000-0000-000000000034', 'a1000000-0000-0000-0000-000000000005', 'A nurse is caring for a postpartum mother who had an episiotomy. What is the appropriate care for the episiotomy site?', 'MC', 'MEDIUM', 'The nurse should provide sitz baths, perineal irrigation after voiding, ice packs for the first 24 hours, and keep the area clean and dry to promote healing.', false, true, NOW(), NOW()),
('b0000005-0000-0000-0000-000000000035', 'a1000000-0000-0000-0000-000000000005', 'A pregnant woman asks about the recommended weight gain during pregnancy. What is the guideline for normal BMI women?', 'MC', 'EASY', 'For women with normal pre-pregnancy BMI (18.5-24.9), the recommended total weight gain during pregnancy is 11.5-16 kg (25-35 lbs).', false, true, NOW(), NOW()),
('b0000005-0000-0000-0000-000000000036', 'a1000000-0000-0000-0000-000000000005', 'What is the most important factor in preventing neonatal tetanus?', 'MC', 'MEDIUM', 'Ensuring that mothers receive at least 2 doses of tetanus toxoid vaccine during pregnancy is the most important factor in preventing neonatal tetanus.', true, true, NOW(), NOW()),
('b0000005-0000-0000-0000-000000000037', 'a1000000-0000-0000-0000-000000000005', 'A nurse is assessing a postpartum mother for signs of postpartum depression. What is the most common symptom?', 'MC', 'MEDIUM', 'Persistent sadness, loss of interest in the baby, fatigue, and difficulty bonding with the newborn are common symptoms of postpartum depression that typically appear within 2-3 weeks after delivery.', false, true, NOW(), NOW());
INSERT INTO nle_question_bank (id, category_id, question_text, question_type, difficulty, explanation, is_high_yield, is_active, created_at, updated_at) VALUES
('b0000006-0000-0000-0000-000000000001', 'a1000000-0000-0000-0000-000000000006', 'What is the most appropriate therapeutic communication technique for a patient experiencing anxiety?', 'MC', 'MEDIUM', 'Active listening and providing a calm, non-judgmental presence are the most appropriate techniques. These help the patient feel heard and reduce anxiety levels.', true, true, NOW(), NOW()),
('b0000006-0000-0000-0000-000000000002', 'a1000000-0000-0000-0000-000000000006', 'A patient with schizophrenia is exhibiting auditory hallucinations. What is the best nursing intervention?', 'MC', 'MEDIUM', 'The nurse should acknowledge the patient''s experience without validating the hallucination, maintain a calm environment, and use reality orientation techniques.', false, true, NOW(), NOW()),
('b0000006-0000-0000-0000-000000000003', 'a1000000-0000-0000-0000-000000000006', 'Which of the following is a priority nursing diagnosis for a patient with major depressive disorder?', 'MC', 'MEDIUM', 'Risk for suicide is the priority nursing diagnosis for patients with major depressive disorder, as depression significantly increases the risk of suicidal ideation and attempts.', true, true, NOW(), NOW()),
('b0000006-0000-0000-0000-000000000004', 'a1000000-0000-0000-0000-000000000006', 'A patient is prescribed lithium for bipolar disorder. What laboratory value should be monitored regularly?', 'MC', 'MEDIUM', 'Lithium has a narrow therapeutic index. Serum lithium levels should be monitored regularly (therapeutic range: 0.6-1.2 mEq/L) to prevent toxicity.', true, true, NOW(), NOW()),
('b0000006-0000-0000-0000-000000000005', 'a1000000-0000-0000-0000-000000000006', 'What is the primary goal of psychiatric medication management?', 'MC', 'EASY', 'The primary goal is to achieve symptom relief with minimal side effects while maintaining the patient''s quality of life and functional abilities.', false, true, NOW(), NOW()),
('b0000006-0000-0000-0000-000000000006', 'a1000000-0000-0000-0000-000000000006', 'A patient with borderline personality disorder is threatening self-harm. What is the most appropriate nursing response?', 'MC', 'HARD', 'The nurse should remain calm, take the threat seriously, ensure the patient''s safety by removing harmful objects, and initiate a therapeutic conversation to explore the underlying feelings.', true, true, NOW(), NOW()),
('b0000006-0000-0000-0000-000000000007', 'a1000000-0000-0000-0000-000000000006', 'Which of the following is a side effect of typical antipsychotic medications?', 'MC', 'MEDIUM', 'Extrapyramidal symptoms (EPS) including dystonia, akathisia, parkinsonism, and tardive dyskinesia are common side effects of typical antipsychotics.', false, true, NOW(), NOW()),
('b0000006-0000-0000-0000-000000000008', 'a1000000-0000-0000-0000-000000000006', 'A nurse is providing crisis intervention to a patient who has experienced a traumatic event. What is the priority?', 'MC', 'MEDIUM', 'Ensuring the patient''s safety and providing emotional support are the priorities. The nurse should help the patient feel secure and establish a sense of control.', true, true, NOW(), NOW()),
('b0000006-0000-0000-0000-000000000009', 'a1000000-0000-0000-0000-000000000006', 'What is the therapeutic dose range of lithium for bipolar disorder?', 'MC', 'EASY', 'The therapeutic serum lithium level for bipolar disorder is 0.6-1.2 mEq/L. Levels above 1.5 mEq/L indicate toxicity and require immediate medical intervention.', false, true, NOW(), NOW()),
('b0000006-0000-0000-0000-000000000010', 'a1000000-0000-0000-0000-000000000006', 'A patient with anxiety disorder is prescribed alprazolam (Xanax). What teaching should the nurse provide?', 'MC', 'MEDIUM', 'The nurse should teach the patient about potential for dependence, avoid sudden discontinuation, avoid alcohol, and report excessive drowsiness or difficulty breathing.', false, true, NOW(), NOW()),
('b0000006-0000-0000-0000-000000000011', 'a1000000-0000-0000-0000-000000000006', 'Which of the following is an example of a positive symptom of schizophrenia?', 'MC', 'MEDIUM', 'Hallucinations, delusions, and disorganized speech are positive symptoms (added behaviors). Negative symptoms include flat affect, social withdrawal, and avolition.', false, true, NOW(), NOW()),
('b0000006-0000-0000-0000-000000000012', 'a1000000-0000-0000-0000-000000000006', 'A nurse is caring for a patient with post-traumatic stress disorder (PTSD). What is the best therapeutic approach?', 'MC', 'MEDIUM', 'Trauma-focused cognitive behavioral therapy (TF-CBT) is the evidence-based treatment of choice for PTSD. The nurse should provide a safe, supportive environment.', false, true, NOW(), NOW()),
('b0000006-0000-0000-0000-000000000013', 'a1000000-0000-0000-0000-000000000006', 'What is the most important factor in establishing a therapeutic nurse-patient relationship?', 'MC', 'EASY', 'Trust is the foundation of the therapeutic nurse-patient relationship. It is established through consistency, honesty, empathy, and maintaining professional boundaries.', true, true, NOW(), NOW()),
('b0000006-0000-0000-0000-000000000014', 'a1000000-0000-0000-0000-000000000006', 'A patient with bipolar disorder is in the manic phase. Which nursing intervention is most appropriate?', 'MC', 'MEDIUM', 'Reducing stimuli, setting limits on behavior, maintaining a calm environment, and ensuring adequate nutrition and hydration are appropriate interventions for manic episodes.', false, true, NOW(), NOW()),
('b0000006-0000-0000-0000-000000000015', 'a1000000-0000-0000-0000-000000000006', 'Which of the following medications is an SSRI commonly used for depression?', 'MC', 'EASY', 'Selective serotonin reuptake inhibitors (SSRIs) such as fluoxetine (Prozac), sertraline (Zoloft), and escitalopram (Lexapro) are first-line treatments for depression.', false, true, NOW(), NOW()),
('b0000006-0000-0000-0000-000000000016', 'a1000000-0000-0000-0000-000000000006', 'A nurse is assessing a patient for suicide risk. Which question is most appropriate to ask directly?', 'MC', 'MEDIUM', '"Are you thinking about killing yourself?" is the most direct and appropriate question to assess suicide risk. Asking directly does not plant the idea but opens the door for the patient to express their feelings.', true, true, NOW(), NOW()),
('b0000006-0000-0000-0000-000000000017', 'a1000000-0000-0000-0000-000000000006', 'What is the primary purpose of milieu therapy in psychiatric settings?', 'MC', 'MEDIUM', 'Milieu therapy uses the therapeutic environment to promote socialization, provide structure, and help patients develop coping skills in a supportive community setting.', false, true, NOW(), NOW()),
('b0000006-0000-0000-0000-000000000018', 'a1000000-0000-0000-0000-000000000006', 'A patient with obsessive-compulsive disorder (OCD) performs hand-washing rituals repeatedly. What is the best nursing approach?', 'MC', 'MEDIUM', 'The nurse should acknowledge the patient''s anxiety without enabling the ritual, help identify triggers, and encourage gradual exposure and response prevention techniques.', false, true, NOW(), NOW()),
('b0000006-0000-0000-0000-000000000019', 'a1000000-0000-0000-0000-000000000006', 'Which of the following is a sign of lithium toxicity?', 'MC', 'HARD', 'Lithium toxicity presents with coarse tremors, nausea, vomiting, diarrhea, confusion, ataxia, and in severe cases, seizures and coma. It requires immediate medical attention.', true, true, NOW(), NOW()),
('b0000006-0000-0000-0000-000000000020', 'a1000000-0000-0000-0000-000000000006', 'A nurse is planning care for a patient with anorexia nervosa. What is the priority nursing diagnosis?', 'MC', 'HARD', 'Imbalanced nutrition: less than body requirements is the priority nursing diagnosis for patients with anorexia nervosa, as it directly impacts physical health and survival.', true, true, NOW(), NOW()),
('b0000006-0000-0000-0000-000000000021', 'a1000000-0000-0000-0000-000000000006', 'What is the difference between delirium and dementia?', 'MC', 'MEDIUM', 'Delirium has acute onset, fluctuating course, and is usually reversible. Dementia has gradual onset, progressive decline, and is generally irreversible.', false, true, NOW(), NOW()),
('b0000006-0000-0000-0000-000000000022', 'a1000000-0000-0000-0000-000000000006', 'A nurse is providing discharge teaching to a patient on clozapine. What is the most important instruction?', 'MC', 'HARD', 'The patient must have regular blood monitoring for agranulocytosis (WBC count), report any signs of infection immediately, and avoid grapefruit juice which affects drug metabolism.', true, true, NOW(), NOW()),
('b0000006-0000-0000-0000-000000000023', 'a1000000-0000-0000-0000-000000000006', 'Which defense mechanism is demonstrated by a patient who refuses to believe a terminal diagnosis?', 'MC', 'MEDIUM', 'Denial is a defense mechanism where the patient refuses to acknowledge reality. It is a common initial response to overwhelming situations.', false, true, NOW(), NOW()),
('b0000006-0000-0000-0000-000000000024', 'a1000000-0000-0000-0000-000000000006', 'A nurse is using therapeutic communication. Which response demonstrates empathy?', 'MC', 'MEDIUM', '"I can see that you are feeling very anxious right now" demonstrates empathy by reflecting the patient''s feelings and showing understanding.', false, true, NOW(), NOW()),
('b0000006-0000-0000-0000-000000000025', 'a1000000-0000-0000-0000-000000000006', 'A patient with substance use disorder is experiencing withdrawal symptoms. What is the priority intervention?', 'MC', 'MEDIUM', 'Ensuring patient safety, monitoring vital signs, providing emotional support, and administering prescribed medications to manage withdrawal symptoms are priority interventions.', false, true, NOW(), NOW()),
('b0000006-0000-0000-0000-000000000026', 'a1000000-0000-0000-0000-000000000006', 'What is the purpose of group therapy in psychiatric settings?', 'MC', 'EASY', 'Group therapy provides peer support, promotes socialization, allows patients to share experiences, learn from others, and develop interpersonal skills in a structured environment.', false, true, NOW(), NOW()),
('b0000006-0000-0000-0000-000000000027', 'a1000000-0000-0000-0000-000000000006', 'A nurse is caring for a patient experiencing a panic attack. What is the best intervention?', 'MC', 'MEDIUM', 'The nurse should stay with the patient, speak in a calm and reassuring manner, help with deep breathing, and provide a quiet, non-stimulating environment.', true, true, NOW(), NOW()),
('b0000006-0000-0000-0000-000000000028', 'a1000000-0000-0000-0000-000000000006', 'Which of the following is a characteristic of antisocial personality disorder?', 'MC', 'MEDIUM', 'Disregard for the rights of others, deceitfulness, impulsivity, irritability, and lack of remorse are hallmark characteristics of antisocial personality disorder.', false, true, NOW(), NOW()),
('b0000006-0000-0000-0000-000000000029', 'a1000000-0000-0000-0000-000000000006', 'What is the significance of the 5 P''s in suicide risk assessment?', 'MC', 'MEDIUM', 'The 5 P''s are: Previous attempts, Plan, Purpose, Pills (access to means), and People (social support). These factors help assess the level of suicide risk.', false, true, NOW(), NOW()),
('b0000006-0000-0000-0000-000000000030', 'a1000000-0000-0000-0000-000000000006', 'A patient with depression is prescribed venlafaxine. What should the nurse monitor for during the first few weeks?', 'MC', 'MEDIUM', 'The nurse should monitor for increased suicidal ideation, especially in the first few weeks of treatment. This is why close follow-up and monitoring are essential.', true, true, NOW(), NOW()),
('b0000006-0000-0000-0000-000000000031', 'a1000000-0000-0000-0000-000000000006', 'What is the most effective way to prevent relapse in patients with substance use disorders?', 'MC', 'MEDIUM', 'Comprehensive aftercare including counseling, support groups (AA/NA), lifestyle modifications, and ongoing medical follow-up are most effective for preventing relapse.', false, true, NOW(), NOW()),
('b0000006-0000-0000-0000-000000000032', 'a1000000-0000-0000-0000-000000000006', 'A nurse is caring for a patient with dementia. Which intervention promotes safety?', 'MC', 'MEDIUM', 'Using simple, clear directions, maintaining consistent routines, ensuring adequate lighting, removing tripping hazards, and using identification bracelets are important safety measures.', false, true, NOW(), NOW()),
('b0000006-0000-0000-0000-000000000033', 'a1000000-0000-0000-0000-000000000006', 'What is the legal basis for involuntary hospitalization in the Philippines?', 'MC', 'HARD', 'R.A. 11036 (Mental Health Act) provides the legal framework for involuntary hospitalization when a person with mental illness poses a danger to themselves or others, or is unable to care for themselves.', true, true, NOW(), NOW()),
('b0000006-0000-0000-0000-000000000034', 'a1000000-0000-0000-0000-000000000006', 'A nurse is using the CAGE questionnaire to assess alcohol use disorder. What does the ''E'' stand for?', 'MC', 'EASY', 'The CAGE questionnaire stands for: Cut down, Annoyed, Guilty, Eye-opener. The ''E'' stands for Eye-opener (needing a drink first thing in the morning).', false, true, NOW(), NOW()),
('b0000006-0000-0000-0000-000000000035', 'a1000000-0000-0000-0000-000000000006', 'What is the primary focus of cognitive behavioral therapy (CBT)?', 'MC', 'EASY', 'CBT focuses on identifying and changing negative thought patterns and behaviors. It helps patients recognize the connection between thoughts, feelings, and behaviors.', false, true, NOW(), NOW()),
('b0000006-0000-0000-0000-000000000036', 'a1000000-0000-0000-0000-000000000006', 'A nurse is caring for a patient experiencing serotonin syndrome. What is the most common cause?', 'MC', 'HARD', 'Serotonin syndrome is most commonly caused by combining serotonergic drugs (SSRIs, MAOIs, triptans). Symptoms include agitation, hyperthermia, tremor, and altered mental status.', false, true, NOW(), NOW()),
('b0000006-0000-0000-0000-000000000037', 'a1000000-0000-0000-0000-000000000006', 'What is the role of a psychiatric nurse specialist in the Philippines?', 'MC', 'MEDIUM', 'The psychiatric nurse specialist provides advanced nursing care to patients with mental health disorders, including assessment, diagnosis, treatment planning, and psychopharmacology management.', false, true, NOW(), NOW());
