-- ============================================================================
-- NLE Seed Data: Philippine Nurse Licensure Examination
-- ============================================================================
-- This script seeds NLE categories (deterministic a1000000-… IDs) and
-- 222 MCQ questions for categories 1-6. With parts 2A/2B and the options
-- files the bank totals 516 questions / 2064 options.
--
-- ⚠️  Run BEFORE `npm run db:seed` — the seed resolves categories by code and
--    builds the practice exam's category_filter from these fixed IDs.
-- Run: psql -U postgres -d nurselearn_ph -f nle-seed-data.sql
-- ============================================================================

BEGIN;

-- ─── 1. Delete existing test categories ──────────────────────────────────────
DELETE FROM nle_question_options
WHERE question_id IN (
  SELECT id FROM nle_question_bank WHERE category_id IN (
    SELECT id FROM nle_categories WHERE code LIKE 'TEST%'
  )
);

DELETE FROM nle_question_bank
WHERE category_id IN (
  SELECT id FROM nle_categories WHERE code LIKE 'TEST%'
);

DELETE FROM nle_categories WHERE code LIKE 'TEST%';

DELETE FROM nle_categories WHERE code IN ('INSTR_CAT_1', 'MedSurg');

-- Wipe earlier duplicate seed/test questions (options cascade-delete)
DELETE FROM nle_question_bank;

-- Rebuild categories so their IDs match the deterministic seed IDs referenced by questions
DELETE FROM nle_categories;

-- ─── 2. Create NLE Categories ────────────────────────────────────────────────
ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description;

-- ─── 3. NLE Questions (518 questions) ────────────────────────────────────────
-- Category IDs:
--   FUNDAMENTALS: a1000000-0000-0000-0000-000000000001
--   MEDSURG:      a1000000-0000-0000-0000-000000000002
--   COMMUNITY:    a1000000-0000-0000-0000-000000000003
--   PEDIATRICS:   a1000000-0000-0000-0000-000000000004
--   OBSTETRIC:    a1000000-0000-0000-0000-000000000005
--   MENTAL:       a1000000-0000-0000-0000-000000000006
--   PHARMA:       a1000000-0000-0000-0000-000000000007
--   ANATOMY:      a1000000-0000-0000-0000-000000000008
--   MICROBIO:     a1000000-0000-0000-0000-000000000009
--   LEADERSHIP:   a1000000-0000-0000-0000-000000000010
--   ETHICS:       a1000000-0000-0000-0000-000000000011
--   NUTRITION:    a1000000-0000-0000-0000-000000000012
--   OR_NURSING:   a1000000-0000-0000-0000-000000000013
--   EMERGENCY:    a1000000-0000-0000-0000-000000000014

